// Adaptive Reaction Engine (Negation/Polarity Tracking)
const text = userMessage ? userMessage.toLowerCase() : "";
const negations = [' non ', ' no ', ' senza ', " don't ", " won't ", " didn't ", ' never ', ' stop ', ' without '];
const angryKeywords = ['arrabbiat', 'odio', 'mad ', 'hate', 'furi', 'angry'];

let angryCount = 0;

angryKeywords.forEach(kw => {
    let regex = new RegExp(kw, 'gi');
    let match;
    while ((match = regex.exec(text)) !== null) {
        let startIndex = Math.max(0, match.index - 25);
        let contextBefore = text.substring(startIndex, match.index);
        let isNegated = false;

        for(let n of negations) {
            if (contextBefore.includes(n)) { isNegated = true; break; }
        }
        if (!isNegated) angryCount++;
    }
});

if (angryCount > 0) {
    addMessage({ role: "user", append: true, content: "[OOC: {{char}} notices your hostility and reacts accordingly.]" });
    // update bitmask logic could go here
    setVariable("emotion_bitmask", "00000001");
}

