const text = userMessage ? userMessage.toLowerCase() : "";
const buyWords = ['compra', 'buy', 'pay', 'paga', 'spend'];
const travelWords = ['viaggia', 'travel', 'drive', 'guida', 'fly', 'vola'];

let spentWealth = 0;
let spentResources = 0;

buyWords.forEach(kw => {
    if (text.includes(kw)) spentWealth += 50;
});

travelWords.forEach(kw => {
    if (text.includes(kw)) {
        spentWealth += 100;
        spentResources += 10;
    }
});

if (spentWealth > 0) {
    setVariable('wealth', spentWealth, 'minus');
    addMessage({ role: "user", append: true, content: "[OOC: Una spesa è stata effettuata, il denaro è diminuito.]" });
}

if (spentResources > 0) {
    setVariable('resources', spentResources, 'minus');
    addMessage({ role: "user", append: true, content: "[OOC: Il viaggio o l'attività logistica ha consumato risorse.]" });
}

