const botMsg = getLastBotMessage();
if (botMsg && botMsg.content) {
    // Cerca pattern tipo Platonic: 10%->13% o Platonic: 10% → 13%
    const parseAttraction = (type) => {
        const regex = new RegExp(type + "\\s*:\s*(?:-?\\d+)%\\s*(?:→|->|>|to|->)\\s*(-?\\d+)%", "i");
        const match = botMsg.content.match(regex);
        if (match && match[1]) {
            // Imposta il valore se trova il nuovo numero!
            setVariable(type.toLowerCase() + "_pct", parseInt(match[1]));
        }
    };
    parseAttraction("Platonic");
    parseAttraction("Romantic");
    parseAttraction("Sexual");
}

