// Parse language from prompt or memory
const textToSearch = (userMessage || "") + " " + (chatMemory || "");
const langMatch = textToSearch.match(/<LANGUAGE=\[?(.*?)\]?>/i);
let targetLang = "English";
if (langMatch && langMatch[1]) {
    targetLang = langMatch[1];
    setVariable("bot_language", targetLang);
} else {
    let storedLang = getVariable("bot_language");
    if (storedLang) targetLang = storedLang;
}

// Append system instruction for language
addMessage({ role: "system", pool: [
  `[System Note: The default/common language is now ${targetLang}. Use English as fallback if not applicable. If the user or NPC knows a specific language, format it as: "original language phrase" (translation in ${targetLang}). Also respect generational or ethnic slangs (e.g. gen-z slang for Jasper, Old Norse for Wulfnic).]`
]});
